export function validatePassword(password){if(typeof password!=='string'||password.length<12||password.length>128)throw Error('Use a password with 12–128 characters. A few memorable words work well.');}
export function parseEmailAction(search){const p=new URLSearchParams(search),code=p.get('oobCode'),mode=p.get('mode');if(p.getAll('oobCode').length!==1||p.getAll('mode').length!==1||!code?.trim()||code.length>4096||!['verifyEmail','resetPassword','recoverEmail'].includes(mode))throw Error('This email link is incomplete. Request a fresh link from Bloom.');return {code,mode};}
export function parseVerificationLink(input,origin,authDomain){let url;try{url=new URL(input.trim());}catch{throw Error('Copy the full verification link from your email.');}if(![new URL(origin).origin,`https://${authDomain}`].includes(url.origin))throw Error('Use the verification link sent by Bloom for this account.');const action=parseEmailAction(url.search);if(action.mode!=='verifyEmail')throw Error('This is not an email verification link.');return action;}
export function authError(error){const messages={'auth/email-already-in-use':'An account already uses this email. Sign in or reset your password.','auth/invalid-credential':'The email or password is incorrect. Please try again.','auth/invalid-email':'Please enter a valid email address.','auth/weak-password':'Use a password with at least 12 characters.','auth/password-does-not-meet-requirements':'Use a password with 12–128 characters.','auth/too-many-requests':'A few too many tries. Wait a little and try again.','auth/network-request-failed':'Could not connect. Check your internet connection and try again.','auth/operation-not-allowed':'This sign-in method is temporarily unavailable. Please try another method.','auth/unauthorized-domain':'Sign-in is not available from this address. Open the published Bloom app.','auth/popup-blocked':'Your browser blocked the Google window. Allow popups for Bloom and try again.','auth/popup-closed-by-user':'The Google window was closed. You can try again whenever you’re ready.','auth/cancelled-popup-request':'Another sign-in window is already open.','auth/account-exists-with-different-credential':'This email uses another sign-in method. Sign in with that method first.','auth/user-disabled':'This account is disabled. Contact the app owner.','auth/expired-action-code':'This email link has expired. Request a new link from Bloom.','auth/invalid-action-code':'This email link is invalid or has already been used. If you already verified your email, sign in to continue.','permission-denied':'Verify your email before opening your cloud data.'};return messages[error?.code]||(error instanceof Error&&!error.code?error.message:'Something didn’t finish. Please try again.');}
